const choice = $input.first().json.choices?.[0];
if (choice?.finish_reason !== 'stop' || choice.message?.refusal) throw new Error('Caption generation incomplete');
const result = JSON.parse(choice.message.content);
const output = { caption: result.caption, hashtags: result.hashtags, language: result.language };
if ($('Authenticated caption webhook').first().json.body.metadata.generationMode === 'creative') {
  output.assetId = result.assetId; output.platform = result.platform; output.creativeReason = result.creativeReason;
  if ($('Authenticated caption webhook').first().json.body.metadata.tourismContext) output.campaignReasoning = result.campaignReasoning;
}
return [{ json: output }];
